// Cada clase, con un contador de pasos. Con n chico, para que las últimas dos terminen.
function constante(lista) { let pasos = 0; const ultimo = lista[lista.length - 1]; pasos++; return pasos; }
function logaritmo(n) { let pasos = 0; for (let k = n; k > 1; k = Math.floor(k / 2)) pasos++; return pasos; }
function lineal(n) { let pasos = 0; for (let i = 0; i < n; i++) pasos++; return pasos; }
function nPorLog(n) { let pasos = 0; for (let i = 0; i < n; i++) pasos += logaritmo(n); return pasos; }
function cuadratico(n) { let pasos = 0; for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) pasos++; return pasos; }
function exponencial(n) { let pasos = 0; for (let mascara = 0; mascara < 2 ** n; mascara++) pasos++; return pasos; }
function factorial(n) {
  let pasos = 0;
  const usado = new Array(n).fill(false);
  (function armar(largo) {
    if (largo === n) { pasos++; return; }
    for (let i = 0; i < n; i++) if (!usado[i]) { usado[i] = true; armar(largo + 1); usado[i] = false; }
  })(0);
  return pasos;
}

console.log("n  |  1 | log n |  n | n log n |  n²  |   2ⁿ   |    n!");
for (const n of [2, 4, 8, 10]) {
