    String(lineal(n)).padStart(2), "|",
    String(nPorLog(n)).padStart(7), "|",
    String(cuadratico(n)).padStart(4), "|",
    String(exponencial(n)).padStart(6), "|",
    String(factorial(n)).padStart(8)
  );
}

// Ordenar con el sort del motor: ¿cuánto crece el tiempo al duplicar n?
function aleatorios(n) { let s = 42; return Array.from({ length: n }, () => (s = (s * 16807) % 2147483647)); }
aleatorios(1000).sort((a, b) => a - b);          // calentamiento
let anterior = 0;
for (const n of [100000, 200000, 400000, 800000]) {
  const datos = aleatorios(n);
  const t0 = performance.now();
  datos.sort((a, b) => a - b);
  const t = performance.now() - t0;
  console.log("n =", String(n).padStart(7), "|", t.toFixed(0).padStart(5), "ms", anterior ? "| x" + (t / anterior).toFixed(2) : "",
    "| cociente esperado para n log n: x" + ((2 * n * Math.log2(2 * n)) / (n * Math.log2(n))).toFixed(2));
  anterior = t;
}

// Fuerza bruta: ¿qué bultos entran mejor en un camión de 777 kg? Se prueban todas las combinaciones.
function mejorCarga(pesos, capacidad) {
  const n = pesos.length;
  let mejor = 0;
  for (let mascara = 0; mascara < 2 ** n; mascara++) {
    let suma = 0;
    for (let i = 0; i < n; i++) if (mascara & (1 << i)) suma += pesos[i];
    if (suma <= capacidad && suma > mejor) mejor = suma;
  }
  return mejor;
}
mejorCarga(Array.from({ length: 16 }, (_, i) => 37 + ((i * 53) % 91)), 777);     // calentamiento
let anterior = 0;
for (const n of [17, 18, 19, 20, 21]) {
  const pesos = Array.from({ length: n }, (_, i) => 37 + ((i * 53) % 91));   // pesos de ejemplo
  const t0 = performance.now();
  const mejor = mejorCarga(pesos, 777);
  const t = performance.now() - t0;
  console.log("bultos:", n, "| combinaciones:", (2 ** n).toLocaleString("es-AR"), "| mejor carga:", mejor, "kg |", t.toFixed(0), "ms", anterior ? "(x" + (t / anterior).toFixed(2) + ")" : "");
  anterior = t;
}

// Viajante por fuerza bruta: probar TODOS los órdenes de visita de n paradas (el depósito queda fijo al principio y al final)
function distancias(n) {
  // «Mapa» de ejemplo: n + 1 puntos (el 0 es el depósito) sobre una grilla inventada
  const pts = Array.from({ length: n + 1 }, (_, i) => [(i * 37) % 23, (i * 53) % 29]);
  return pts.map(a => pts.map(b => Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1])));
}
function probarTodos(n) {
  const d = distancias(n);
  const usada = new Array(n + 1).fill(false);
  let mejor = Infinity, ordenes = 0;
  function armar(actual, visitadas, km) {
    if (visitadas === n) { ordenes++; mejor = Math.min(mejor, km + d[actual][0]); return; }
    for (let p = 1; p <= n; p++) if (!usada[p]) { usada[p] = true; armar(p, visitadas + 1, km + d[actual][p]); usada[p] = false; }
  }
  armar(0, 0, 0);
  return { mejor, ordenes };
}
probarTodos(7);          // calentamiento
let anterior = 0;
for (const n of [8, 9, 10]) {
  const t0 = performance.now();
  const r = probarTodos(n);
  const t = performance.now() - t0;
  console.log("paradas:", n, "| órdenes probados:", r.ordenes.toLocaleString("es-AR"), "| mejor:", r.mejor, "km |", t.toFixed(1), "ms", anterior ? "(x" + (t / anterior).toFixed(1) + ")" : "");
  anterior = t;
}

// Dos formas de contestar «¿hay dos entregas con el mismo código?» sobre n números
// A: compara todos los pares (n²/2 pasos, cada uno baratísimo)
function conPares(codigos) {
  for (let i = 0; i < codigos.length; i++)
    for (let j = i + 1; j < codigos.length; j++)
      if (codigos[i] === codigos[j]) return true;
  return false;
}
// B: un solo recorrido (n elementos), pero a cada uno le hace un trabajo de preparación pesado: 2.000 vueltas de relleno
function conPreparacion(codigos) {
  const vistos = new Set();
  let basura = 0;
  for (const c of codigos) {
    for (let k = 0; k < 2000; k++) basura += (c ^ k) & 1;   // el «costo escondido» por elemento
    if (vistos.has(c)) return true;
    vistos.add(c);
  }
  return basura < 0;
}
function medir(f, datos) { const t0 = performance.now(); f(datos); return performance.now() - t0; }
const sinRepetidos = n => Array.from({ length: n }, (_, i) => i);   // peor caso: no hay repetidos
conPares(sinRepetidos(100)); conPreparacion(sinRepetidos(100));
console.log("      n |  A: pares (ms) | B: un recorrido pesado (ms)");
for (const n of [250, 500, 1000, 2000, 4000, 8000, 16000]) {
  const datos = sinRepetidos(n);
  console.log(String(n).padStart(7), "|", medir(conPares, datos).toFixed(2).padStart(14), "|", medir(conPreparacion, datos).toFixed(2).padStart(10));
}

// ¿Recorrer una lista (includes) o consultar un conjunto (Set.has)? Con n chico casi no hay diferencia; con n grande, sí.
function nsPorConsulta(f, repeticiones) {
  const t0 = performance.now();
  let r = 0;
  for (let k = 0; k < repeticiones; k++) r += f() ? 1 : 0;
  return ((performance.now() - t0) * 1e6) / repeticiones;     // nanosegundos
}
console.log("     n | lista (ns) | conjunto (ns)");
for (const n of [4, 16, 64, 256, 1024, 8192]) {
  const lista = Array.from({ length: n }, (_, i) => i * 3);
  const conjunto = new Set(lista);
  const buscado = lista[n - 1];                       // el peor caso para la lista: está al final
  const reps = Math.round(1e6 / Math.max(1, n / 64));
  nsPorConsulta(() => lista.includes(buscado), 20000);   // calentamiento
  nsPorConsulta(() => conjunto.has(buscado), 20000);
  const tL = nsPorConsulta(() => lista.includes(buscado), reps);
  const tC = nsPorConsulta(() => conjunto.has(buscado), reps);
  console.log(String(n).padStart(6), "|", tL.toFixed(1).padStart(10), "|", tC.toFixed(1).padStart(12));
}

// Mismo trabajo (sumar n números), dos órdenes de recorrido
const N = 1 << 22;                       // 4.194.304 números (16 MB)
const datos = new Int32Array(N);
for (let i = 0; i < N; i++) datos[i] = i & 255;
// Orden «en fila»: 0, 1, 2, 3...  Orden «saltando»: todas las posiciones en un orden pseudoaleatorio
const orden = new Int32Array(N);
for (let i = 0; i < N; i++) orden[i] = i;
let semilla = 7;
for (let i = N - 1; i > 0; i--) { semilla = (semilla * 1103515245 + 12345) & 0x7fffffff; const j = semilla % (i + 1); const t = orden[i]; orden[i] = orden[j]; orden[j] = t; }
function enFila() { let s = 0; for (let i = 0; i < N; i++) s += datos[i]; return s; }
function saltando() { let s = 0; for (let i = 0; i < N; i++) s += datos[orden[i]]; return s; }
enFila(); saltando();
let t0 = performance.now(); const a = enFila(); const tFila = performance.now() - t0;
t0 = performance.now(); const b = saltando(); const tSalto = performance.now() - t0;
console.log("mismo resultado:", a === b, "| en fila:", tFila.toFixed(1), "ms | saltando:", tSalto.toFixed(1), "ms | cociente:", (tSalto / tFila).toFixed(1));

// Estimar antes de correr: medir con un n chico y extrapolar con la forma del crecimiento
function puntos(n) {
  let s = 99;
  const az = () => (s = (s * 16807) % 2147483647) / 2147483647;
  const x = new Float64Array(n), y = new Float64Array(n);
  for (let i = 0; i < n; i++) { x[i] = az() * 20000; y[i] = az() * 20000; }   // metros, en un cuadrado de 20 × 20 km
  return { x, y, n };
}
// ¿Cuántos pares de entregas quedan a menos de 100 m? (todas contra todas)
function paresCercanos({ x, y, n }) {
  let cuantos = 0;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++) {
      const dx = x[i] - x[j], dy = y[i] - y[j];
      if (dx * dx + dy * dy < 100 * 100) cuantos++;
    }
  return cuantos;
}
const pares = n => n * (n - 1) / 2;
function milis(n, veces) {                      // el mejor de varios intentos, para que el ruido pese menos
  const p = puntos(n); let mejor = Infinity;
  for (let k = 0; k < veces; k++) { const t0 = performance.now(); paresCercanos(p); mejor = Math.min(mejor, performance.now() - t0); }
  return mejor;
}
milis(3000, 2);                                 // calentamiento
const base = milis(8000, 3);
console.log("n = 8.000: medido", base.toFixed(0), "ms para", pares(8000).toLocaleString("es-AR"), "pares =", (base * 1e6 / pares(8000)).toFixed(2), "ns por par");
for (const n of [4000, 16000]) {
  const previsto = base * pares(n) / pares(8000);
  console.log("n =", n.toLocaleString("es-AR").padStart(6), "| previsto:", previsto.toFixed(0).padStart(4), "ms | medido:", milis(n, 1).toFixed(0).padStart(4), "ms");
}
for (const n of [200000, 2000000]) {
  const s = base * pares(n) / pares(8000) / 1000;
  console.log("n =", n.toLocaleString("es-AR").padStart(9), "| previsto:", s < 3600 ? (s / 60).toFixed(1) + " min" : (s / 3600).toFixed(1) + " h");
}
